    '--ki-step-bg': 'linear-gradient(180deg,#ffffff,#f2f2f2)', // termostat-stepper (mørk: #484848→#3f3f3f)
    '--ki-step-sh': 'inset 0 0 0 1px rgba(0,0,0,0.06),0 2px 8px rgba(0,0,0,0.10)',
