      return ids.map((id) => ({ id, name: nm(id), on: sel.includes(id), noise: h && h.states[id] ? MM_NOISE(h, id) : false, sub: (h && h.states[id] ? mmPlat(h, id) : 'finnes ikke') + (cnt[nm(id).toLowerCase()] > 1 ? ' · ' + id.split('.').pop() : '') }));
