  function unwrapStack(c) {
    if (c && c.type === 'vertical-stack' && Array.isArray(c.cards) && isPopup(c.cards[0])) {
      const [p, ...rest] = c.cards;
      return { ...p, cards: [...(p.cards || []), ...rest] };
    }
    return c;
  }
