      const bar = f.querySelector('[data-mth-pv] .mtb');
      if (bar) { const s = scale(px); ['th', 'th2', 'tf', 'ti', 'tp'].forEach((k) => bar.style.setProperty('--msh-' + k, { th: s.h, th2: s.h2, tf: s.f, ti: s.i, tp: s.p }[k] + 'px')); }
