  const attrs = (a) => Object.keys(a || {}).filter((k) => a[k] != null && a[k] !== false).map((k) => (a[k] === true ? k : `${k}="${esc(a[k])}"`)).join(' ');
  const sym = (s) => `<span class="u-sym">${esc(s)}</span>`;
