        const l = o.lights != null ? o.lights : st && st.attributes.lights != null ? parseFloat(st.attributes.lights).toFixed(0) : '–';
        lab = `${esc(t)}°${sym(has(o.alt_text) ? o.alt_text : `${l} lys på`)}`;
