    get actionStyle() { let g = ''; try { g = M.store && M.store.get ? M.store.get('action_style') : ''; } catch (e) { g = ''; } const a = this.getAttribute('action-style') || g || 'ruter'; return String(a).toLowerCase() === 'liste' ? 'liste' : 'ruter'; }
