        const rs = its.map((b) => b.getBoundingClientRect()), a = rs[0], z = rs[rs.length - 1];
        st.on = true; st.ax = rs.length > 1 && Math.abs(z.left - a.left) > Math.abs(z.top - a.top) ? 'x' : 'y'; st.its = its; st.i = i; st.to = i;
        st.c = rs.map((r) => ctr(r, st.ax));
