  const STAGES = [['awake', 'Våken', 'var(--ki-text-3, var(--gray600,#7f7f7f))', 35], ['light', 'Lett', C.blue, 60], ['deep', 'Dyp', C.purple, 100], ['rem', 'REM', C.purple, 80]];
