          const pts = ((r && r[e.pid]) || []).map((p) => ({ s: p.s != null ? p.s : p.state, t: p.lu != null ? p.lu * 1000 : p.lc != null ? p.lc * 1000 : new Date(p.last_changed || p.last_updated).getTime() }));
