      const chip = sc != null ? `<div class="sc" style="background:${M.alpha(col, 0.16)};color:${M.theme.accentText(col)}">${sc >= 80 ? 'God natt' : sc >= 70 ? 'Grei natt' : 'Urolig natt'}</div>` : '';
