      if (!sp || !lc || !sp.isConnected) return;
      const cur = this._tFit || {}, pil = t.querySelector('.pil');
      const fsNow = parseFloat(getComputedStyle(sp).fontSize) || 30, fs0 = cur.fs ? cur.fs0 : fsNow;
