  const CAM_ONLY = [['away', 'Alle borte'], ['home', 'Noen hjemme'], ['night', 'Natt'], ['armed', 'Alarm armert'], ['entity', 'Egen entitet']];
  const CAM_STYLES = [['tint', 'Tonet'], ['solid', 'Fylt'], ['pink', 'Rosa'], ['icon', 'Bare ikon']];
