                const badge = `<div class="small" style="padding:0 6px;color:${res === true ? 'var(--ki-green-text, #8fd9a8)' : 'var(--ki-text-mid, #979797)'}">${res === true ? 'Slår til nå' : ok.error ? 'Ugyldig: ' + M.esc(ok.error) : 'Nei nå'}</div>`;
