      if (!F.isOn) { if (d < 0) return; this._pend['fan|' + id] = { v: Math.round(F.step), t: Date.now() }; this.update(); return M.call(h, 'fan', 'turn_on', { entity_id: id, percentage: Math.round(F.step) }).catch(() => {}); }
