  const LEG_ROLE = { varmepumpe: 'heat', pumpe: 'pump', lys: 'light', stillemodus: 'quiet', stikkontakt: 'sock', vanntemp: 'water', ute: 'ute', pooltak: 'cover' };
  const LEG_KEYS = ['navn', 'hurtig', 'hurtig_navn', 'hero', 'forvalg', 'ctl', 'ctlHide', 'tabHide', 'ents'];
