        const summary = `Klortablett${d.name ? ' · ' + d.name : ''}${q > 1 ? ' ×' + q : ''}`;
        await M.call(h, 'calendar', 'create_event', { entity_id: e.klor_calendar, summary, start_date_time: t.toISOString(), end_date_time: new Date(t.getTime() + 300000).toISOString() });
