    s += `<rect x="${x - 1.3}" y="${y - 1.3}" width="${w + 2.6}" height="${h + 2.6}" rx=".8" fill="${fr}"/>`;
    s += `<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${lit ? `url(#${p}-lit)` : DARK}"/>`;
