  // Popup-registrering: #tesla (02-popups FUNCTION_POPUPS, 04-strategy vilkår) – bare når Tesla-entiteter finnes
  M.popupNeeds = M.popupNeeds || {};
  if (!M.popupNeeds[HASH]) M.popupNeeds[HASH] = (h) => M.teslaHas(h);
