      if (inn) { if (anim && !(M.animOff && M.animOff())) { inn.style.transition = 'transform .25s cubic-bezier(.3,.8,.3,1)'; setTimeout(() => { inn.style.transition = ''; }, 280); } inn.style.transform = 'translate(0px, 0px) scale(1)'; }
