  const curOrd = (host, key, ids) => { const S = st(host); if (S.drag && S.drag.key === key && S.drag.order.some((x) => ids.includes(x))) return ordOf(S.drag.order, ids); return ordOf(((host.config || {}).ord || {})[key], ids); };
