    L.forEach((x) => { if ((x.v / tot) * 100 < 2 || /^annet$/i.test(x.l)) { if (!other) other = { l: 'Annet', v: 0, c: /^annet$/i.test(x.l) ? x.c : ANNET_C, annet: true }; if (/^annet$/i.test(x.l)) other.c = x.c; other.v += x.v; } else out.push(x); });
    if (other) out.push(other);
