  const allIds = (ids) => [...ids.energy, ids.spot, ids.norge, ids.nord].filter((x, i, a) => x && a.indexOf(x) === i);
  // Timedata bare for det som trenger timer: i dag, denne uken og denne måneden (effekttrinn) → fra min(mandag, 1. i mnd)
